<?php
namespace App\Http\Controllers;
use App\Models\{PortalPrivacyState as State,PortalPrivacyNotice as Notice,PortalPrivacyCase as Review};
use App\Support\{PortalPrivacy as P,LearningAccess};
use Illuminate\Http\Request;
use Illuminate\Support\Str;
class PortalPrivacyController extends Controller {
 private function view(string $name,array $data=[]){return response()->view('privacy.'.$name,$data)->header('Cache-Control','no-store, private')->header('Referrer-Policy','no-referrer');}
 private function admin(Request $r):void {abort_unless(LearningAccess::manager($r->user()),403);}
 public function public(){return $this->view('public',['notice'=>P::current()]);}
 public function form(Request $r){return $this->view('form',['notice'=>P::current(),'case'=>P::open($r->user()),'token'=>(string)Str::uuid()]);}
 public function acknowledge(Request $r){$d=$r->validate(['notice_id'=>'required|uuid','body_hash'=>'required|regex:/^[a-f0-9]{64}$/D','acknowledged'=>'accepted']);P::acknowledge($r->user(),(int)$r->session()->get('auth_version'),$d['notice_id'],$d['body_hash']);return redirect('/')->with('status','Privacy notice acknowledgement recorded for this version.');}
 public function concern(Request $r){$d=$r->validate(['notice_id'=>'required|uuid','body_hash'=>'required|regex:/^[a-f0-9]{64}$/D','request_token'=>'required|uuid','privacy_concern'=>'required|string|max:2000','confirmed'=>'accepted']);P::concern($r->user(),(int)$r->session()->get('auth_version'),$d['notice_id'],$d['body_hash'],$d['request_token'],$d['privacy_concern']);return to_route('portal-privacy.form')->with('status','Your concern has been received for human review. Protected interactive use is paused; notice, contact and sign out remain available.');}
 public function adminIndex(Request $r){$this->admin($r);$r->validate(['page'=>'nullable|integer|min:1']);return $this->view('admin',['state'=>State::findOrFail(1),'notices'=>Notice::orderByDesc('created_at')->get(),'cases'=>Review::whereNotNull('open_user_id')->orderBy('created_at')->paginate(20),'ceo'=>$r->user()->role==='ceo']);}
 public function draft(Request $r){$this->admin($r);$d=$r->validate(['label'=>'required|string|max:100','privacy_body'=>'required|string|min:200|max:50000','contact'=>'required|email|max:250','verification'=>'required|array','verification.*'=>'nullable|string|max:2000','confirmed'=>'accepted']);P::draft($r->user(),(int)$r->session()->get('auth_version'),$d['label'],$d['privacy_body'],$d['contact'],$d['verification']);return back()->with('status','Immutable private draft saved. CEO approval with every verified reference is required for publication.');}
 public function publish(Request $r,Notice $notice){$this->admin($r);$d=$r->validate(['revision'=>'required|integer|min:1','confirmed'=>'accepted']);P::publish($r->user(),(int)$r->session()->get('auth_version'),$notice,(int)$d['revision']);return back()->with('status','Approved notice is public. Review the separate first-login rollout control.');}
 public function enable(Request $r){$this->admin($r);$d=$r->validate(['revision'=>'required|integer|min:1','enabled'=>'required|boolean','privacy_reason'=>'required|string|max:2000','confirmed'=>'accepted']);P::enable($r->user(),(int)$r->session()->get('auth_version'),(int)$d['revision'],(bool)$d['enabled'],$d['privacy_reason']);return back()->with('status','Privacy acknowledgement rollout control updated.');}
 public function decide(Request $r,Review $review){$this->admin($r);$d=$r->validate(['version'=>'required|integer|min:1','action'=>'required|in:Resolved,Alternative,Archive-review,Deletion-review','review_on'=>'nullable|date_format:Y-m-d','privacy_reason'=>'required|string|max:2000','recovery'=>'nullable|boolean','confirmed'=>'accepted']);P::decide($r->user(),(int)$r->session()->get('auth_version'),$review,(int)$d['version'],$d['action'],$d['review_on']??null,$d['privacy_reason'],(bool)($d['recovery']??false));return back()->with('status','Human review decision recorded. No acknowledgement, archive or deletion was fabricated.');}
}
